43	export function calculateHazardLevel(record: Tier3StateRecord | ChannelStateRecord): number {
44	  const s3 = record.score_3_count.length;
45	  const s4 = record.score_4_count.length;
46	  const s5 = record.score_5_count.length;
47	  const s6 = record.score_6_count.length;
48	  const s7 = record.score_7_count.length;
49	
50	  const rawXP = 10 * s5 + 65 * s6 + 200 * s7 - 70 * s3 - 3 * s4;
51	  if (rawXP === 0) return 3.0;
52	
53	  const sgn = rawXP >= 0 ? 1 : -1;
54	  const scalingCoefficient = 5.0 / Math.log(51);
55	  const score = 3.0 + sgn * scalingCoefficient * Math.log(1 + Math.abs(rawXP) / 300);
56	
57	  return Math.round(score * 100) / 100;
58	}
