70	export function getDominantTimeblock(record: Tier3StateRecord | ChannelStateRecord): string | null {
71	  const arcCounts = [
72	    { key: 'timeblock_arc0', count: record.timeblock_arc0 },
73	    { key: 'timeblock_arc1', count: record.timeblock_arc1 },
74	    { key: 'timeblock_arc2', count: record.timeblock_arc2 },
75	    { key: 'timeblock_arc3', count: record.timeblock_arc3 },
76	    { key: 'timeblock_arc4', count: record.timeblock_arc4 },
77	  ];
78	  arcCounts.sort((a, b) => b.count - a.count);
79	  const highest = arcCounts[0];
80	  return highest && highest.count > 0 ? ARC_METADATA[highest.key]?.title || null : null;
81	}
