83	function parseJsonArray(val: unknown): string[] {
84	  if (Array.isArray(val)) return val;
85	  if (typeof val === 'string' && val.trim() !== '') {
86	    try {
87	      const parsed = JSON.parse(val);
88	      return Array.isArray(parsed) ? parsed : [];
89	    } catch {
90	      return [];
91	    }
92	  }
93	  return [];
94	}
