133	export async function rateChannelDirect(
134	  projectId: string,
135	  channelId: string,
136	  channelName: string,
137	  action: string,
138	  timeblocks: string[] = []
139	): Promise<{ success: boolean; hazard: number; played: number; record: ChannelStateRecord }> {
140	  const currentChannels = await fetchChannelState(projectId);
141	  const chRecord: ChannelStateRecord = currentChannels[channelId] || {
142	    channel_id: channelId,
143	    channel_name: channelName,
144	    score_3_count: [],
145	    score_4_count: [],
146	    score_5_count: [],
147	    score_6_count: [],
148	    score_7_count: [],
149	    timeblock_arc0: 0,
150	    timeblock_arc1: 0,
151	    timeblock_arc2: 0,
152	    timeblock_arc3: 0,
153	    timeblock_arc4: 0,
154	    unlock_date: null,
155	  };
156	
157	  const timestampHex = Date.now().toString(16).toUpperCase();
158	  const act = action.toLowerCase().trim();
159	
160	  if (act === '3+' || act === 'cancel' || act === 'downvote') {
161	    chRecord.score_3_count.push(timestampHex);
162	  } else if (act === '4+') {
163	    chRecord.score_4_count.push(timestampHex);
164	  } else if (act === '5+' || act === 'continue') {
165	    chRecord.score_5_count.push(timestampHex);
166	  } else if (act === '6+' || act === 'upvote') {
167	    chRecord.score_6_count.push(timestampHex);
168	  } else if (act === '7+' || act === 'overflow') {
169	    chRecord.score_7_count.push(timestampHex);
170	  }
171	
172	  if (timeblocks && timeblocks.length > 0) {
173	    timeblocks.forEach((b) => {
174	      if (/arc\s*zero|kick/i.test(b)) chRecord.timeblock_arc0++;
175	      else if (/arc\s*0?1|morning/i.test(b)) chRecord.timeblock_arc1++;
176	      else if (/arc\s*0?2|battle/i.test(b)) chRecord.timeblock_arc2++;
177	      else if (/arc\s*0?3|night/i.test(b)) chRecord.timeblock_arc3++;
178	      else if (/arc\s*0?4|sacred/i.test(b)) chRecord.timeblock_arc4++;
179	    });
180	  }
181	
182	  chRecord.updated_at = new Date().toISOString();
183	
184	  // 1. Upsert into channel_state table in _3_state.db
185	  await executeOrder({
186	    project_id: projectId,
187	    tier: 'channel_state',
188	    order: {
189	      action: 'upsert',
190	      key: channelId,
191	      data: {
192	        channel_name: channelName,
193	        score_3_count: JSON.stringify(chRecord.score_3_count),
194	        score_4_count: JSON.stringify(chRecord.score_4_count),
195	        score_5_count: JSON.stringify(chRecord.score_5_count),
196	        score_6_count: JSON.stringify(chRecord.score_6_count),
197	        score_7_count: JSON.stringify(chRecord.score_7_count),
198	        timeblock_arc0: chRecord.timeblock_arc0,
199	        timeblock_arc1: chRecord.timeblock_arc1,
200	        timeblock_arc2: chRecord.timeblock_arc2,
201	        timeblock_arc3: chRecord.timeblock_arc3,
202	        timeblock_arc4: chRecord.timeblock_arc4,
203	        unlock_date: chRecord.unlock_date,
204	        updated_at: chRecord.updated_at,
205	      },
206	    },
207	  });
208	
209	  // 2. Also record to Tier 2 JSONL event buffer
210	  await executeOrder({
211	    project_id: projectId,
212	    tier: '2',
213	    order: {
214	      action: 'append',
215	      data: {
216	        id: channelId,
217	        target_type: 'channel',
218	        channel_id: channelId,
219	        channel_name: channelName,
220	        action: action,
221	        timestamp: timestampHex,
222	        timeblock: timeblocks.length === 1 ? timeblocks[0] : timeblocks.length > 1 ? timeblocks : undefined,
223	      },
224	    },
225	  });
226	
227	  const hazard = calculateHazardLevel(chRecord);
228	  const played = calculateTotalPlayed(chRecord);
229	
230	  return { success: true, hazard, played, record: chRecord };
231	}
