233	export async function fetchEligibleTier4List(
234	  projectId: string,
235	  forceRefresh = false
236	): Promise<VinylDisplayCard[]> {
237	  if (!forceRefresh && cachedEligibleTier4List) {
238	    return cachedEligibleTier4List;
239	  }
240	
241	  const t4Res = await executeOrder<Record<string, Record<string, unknown>>>({
242	    project_id: projectId,
243	    tier: '4',
244	    order: { action: 'read_all' },
245	  });
246	  const t4Data = t4Res.data || {};
247	
248	  const list: VinylDisplayCard[] = [];
249	  let indexCounter = 1;
250	
251	  for (const [id, rawT4] of Object.entries(t4Data)) {
252	    const t4Item = (rawT4 as Record<string, unknown>) || {};
253	    const rawHazard = t4Item.hazard_level;
254	    const hazard =
255	      rawHazard !== undefined && rawHazard !== null && !isNaN(Number(rawHazard))
256	        ? Number(rawHazard)
257	        : 3.0;
258	
259	    if (hazard <= 3.0) continue;
260	
261	    const rawPlayed = t4Item.played;
262	    const played =
263	      rawPlayed !== undefined && rawPlayed !== null && !isNaN(Number(rawPlayed))
264	        ? Number(rawPlayed)
265	        : 0;
266	
267	    list.push({
268	      id,
269	      dbIndex: indexCounter++,
270	      title: `Track ${id}`,
271	      channel: '',
272	      duration: null,
273	      hazard_level: hazard,
274	      played,
275	      timeblock: (t4Item.timeblock as string) || null,
276	      unlock_date: (t4Item.unlock_date as string) || null,
277	      rankCategory: getRankFromScore(hazard),
278	    });
279	  }
280	
281	  cachedEligibleTier4List = list;
282	  return list;
283	}
