288	export async function resolvePageMetadataOnDemand(
289	  projectId: string,
290	  pageTracks: VinylDisplayCard[]
291	): Promise<VinylDisplayCard[]> {
292	  if (pageTracks.length === 0) return [];
293	
294	  const missingIds = pageTracks
295	    .map((t) => t.id)
296	    .filter((id) => !tier1MemoryCache[id]);
297	
298	  if (missingIds.length > 0) {
299	    try {
300	      const res = await executeOrder<Record<string, Tier1StaticItem>>({
301	        project_id: projectId,
302	        tier: '1',
303	        order: { action: 'batch_read', data: missingIds },
304	      });
305	      const dataMap = res.data || {};
306	      for (const [id, staticInfo] of Object.entries(dataMap)) {
307	        tier1MemoryCache[id] = staticInfo;
308	      }
309	    } catch (e) {
310	      console.warn(`[LazyTier1 Batch] Lỗi tải batch ${missingIds.length} items:`, e);
311	    }
312	  }
313	
314	  return pageTracks.map((item) => {
315	    const staticInfo = tier1MemoryCache[item.id];
316	    return {
317	      ...item,
318	      title: staticInfo?.title || item.title,
319	      channel:
320	        staticInfo?.channel_name ||
321	        staticInfo?.channel ||
322	        staticInfo?.artist ||
323	        'Unknown Origin',
324	      duration: staticInfo?.duration ?? null,
325	    };
326	  });
327	}
