353	export async function syncRawinfoMinusBlacklistToTier1(projectId: string): Promise<{
354	  totalActive: number;
355	  excludedCount: number;
356	}> {
357	  await executeOrder({
358	    project_id: projectId,
359	    tier: 'rawinfo',
360	    order: { action: 'seed_if_missing', data: { source_tier: '1' } },
361	  });
362	
363	  const [blacklistRes, badKpiRes] = await Promise.all([
364	    executeOrder<Record<string, Record<string, unknown>>>({
365	      project_id: projectId,
366	      tier: 'blacklist',
367	      order: { action: 'read_all' },
368	    }),
369	    executeOrder<Record<string, Record<string, unknown>>>({
370	      project_id: projectId,
371	      tier: 'bad_kpi',
372	      order: { action: 'read_all' },
373	    }),
374	  ]);
375	
376	  const excludedIds = Array.from(
377	    new Set([
378	      ...Object.keys(blacklistRes.data || {}),
379	      ...Object.keys(badKpiRes.data || {}),
380	    ])
381	  );
382	
383	  if (excludedIds.length > 0) {
384	    await executeOrder({
385	      project_id: projectId,
386	      tier: '1',
387	      order: {
388	        action: 'batch_delete',
389	        data: excludedIds,
390	      },
391	    });
392	  }
393	
394	  for (const k in tier1MemoryCache) delete tier1MemoryCache[k];
395	  invalidateVinylCache(projectId);
396	
397	  return {
398	    totalActive: 0,
399	    excludedCount: excludedIds.length,
400	  };
401	}
