675	export async function syncTier3ToTier4(projectId: string) {
676	  // Fetch full blacklist and bad_kpi to strictly prevent them in Tier 4
677	  const [blacklistRes, badKpiRes] = await Promise.all([
678	    executeOrder<Record<string, Record<string, unknown>>>({
679	      project_id: projectId,
680	      tier: 'blacklist',
681	      order: { action: 'read_all' },
682	    }),
683	    executeOrder<Record<string, Record<string, unknown>>>({
684	      project_id: projectId,
685	      tier: 'bad_kpi',
686	      order: { action: 'read_all' },
687	    }),
688	  ]);
689	
690	  const excludedIds = Array.from(
691	    new Set([
692	      ...Object.keys(blacklistRes.data || {}),
693	      ...Object.keys(badKpiRes.data || {}),
694	    ])
695	  );
696	  const excludedSet = new Set(excludedIds);
697	
698	  const [t3Records, channelRecords] = await Promise.all([
699	    fetchTier3State(projectId),
700	    fetchChannelState(projectId),
701	  ]);
702	
703	  const badKpiMap: Record<string, { id: string; hazard_level: number; purged_at: string }> = {};
704	  const t4ValidBatchMap: Record<string, Record<string, unknown>> = {};
705	  const t3PurgeIds: string[] = [];
706	
707	  // Index individual track ratings
708	  const trackMap: Record<string, Tier3StateRecord> = {};
709	  for (const t3 of t3Records) {
710	    if (excludedSet.has(t3.id)) {
711	      t3PurgeIds.push(t3.id);
712	      continue;
713	    }
714	    trackMap[t3.id] = t3;
715	  }
716	
717	  // Fetch track lists for rated channels to apply channel-wide metadata
718	  const activeChannelIds = Object.keys(channelRecords).filter((id) => !excludedSet.has(id));
719	  const channelTracksMap: Record<string, string[]> = {};
720	
721	  if (activeChannelIds.length > 0) {
722	    try {
723	      const chTracksRes = await executeOrder<Record<string, string[]>>({
724	        project_id: projectId,
725	        tier: '1',
726	        order: {
727	          action: 'get_channel_tracks',
728	          data: { channel_ids: activeChannelIds },
729	        },
730	      });
731	      if (chTracksRes.data) {
732	        Object.assign(channelTracksMap, chTracksRes.data);
733	      }
734	    } catch (e) {
735	      console.warn('[syncTier3ToTier4] Error fetching channel tracks:', e);
736	    }
737	  }
738	
739	  const processedSongIds = new Set<string>();
740	
741	  // Process all songs belonging to rated channels (channel metadata applies to every song of that channel)
742	  for (const chId of activeChannelIds) {
743	    const ch = channelRecords[chId];
744	    const songsInChannel = channelTracksMap[chId] || [];
745	
746	    for (const songId of songsInChannel) {
747	      if (excludedSet.has(songId)) continue;
748	      processedSongIds.add(songId);
749	
750	      const individualT3 = trackMap[songId];
751	      let compositeRecord: Tier3StateRecord;
752	
753	      if (individualT3) {
754	        compositeRecord = {
755	          id: songId,
756	          score_3_count: [...ch.score_3_count, ...individualT3.score_3_count],
757	          score_4_count: [...ch.score_4_count, ...individualT3.score_4_count],
758	          score_5_count: [...ch.score_5_count, ...individualT3.score_5_count],
759	          score_6_count: [...ch.score_6_count, ...individualT3.score_6_count],
760	          score_7_count: [...ch.score_7_count, ...individualT3.score_7_count],
761	          timeblock_arc0: ch.timeblock_arc0 + individualT3.timeblock_arc0,
762	          timeblock_arc1: ch.timeblock_arc1 + individualT3.timeblock_arc1,
763	          timeblock_arc2: ch.timeblock_arc2 + individualT3.timeblock_arc2,
764	          timeblock_arc3: ch.timeblock_arc3 + individualT3.timeblock_arc3,
765	          timeblock_arc4: ch.timeblock_arc4 + individualT3.timeblock_arc4,
766	          unlock_date: individualT3.unlock_date || ch.unlock_date,
767	        };
768	      } else {
769	        compositeRecord = {
770	          id: songId,
771	          score_3_count: [...ch.score_3_count],
772	          score_4_count: [...ch.score_4_count],
773	          score_5_count: [...ch.score_5_count],
774	          score_6_count: [...ch.score_6_count],
775	          score_7_count: [...ch.score_7_count],
776	          timeblock_arc0: ch.timeblock_arc0,
777	          timeblock_arc1: ch.timeblock_arc1,
778	          timeblock_arc2: ch.timeblock_arc2,
779	          timeblock_arc3: ch.timeblock_arc3,
780	          timeblock_arc4: ch.timeblock_arc4,
781	          unlock_date: ch.unlock_date,
782	        };
783	      }
784	
785	      const hazard = calculateHazardLevel(compositeRecord);
786	
787	      if (hazard < 2.0) {
788	        badKpiMap[songId] = {
789	          id: songId,
790	          hazard_level: hazard,
791	          purged_at: new Date().toISOString(),
792	        };
793	        continue;
794	      }
795	
796	      t4ValidBatchMap[songId] = {
797	        id: songId,
798	        hazard_level: hazard,
799	        played: calculateTotalPlayed(compositeRecord),
800	        timeblock: getDominantTimeblock(compositeRecord),
801	        unlock_date: compositeRecord.unlock_date,
802	      };
803	    }
804	  }
805	
806	  // Process remaining individual track ratings whose channels weren't batch rated
807	  for (const t3 of t3Records) {
808	    if (processedSongIds.has(t3.id) || excludedSet.has(t3.id)) continue;
809	
810	    const hazard = calculateHazardLevel(t3);
811	
812	    if (hazard < 2.0) {
813	      badKpiMap[t3.id] = {
814	        id: t3.id,
815	        hazard_level: hazard,
816	        purged_at: new Date().toISOString(),
817	      };
818	      continue;
819	    }
820	
821	    t4ValidBatchMap[t3.id] = {
822	      id: t3.id,
823	      hazard_level: hazard,
824	      played: calculateTotalPlayed(t3),
825	      timeblock: getDominantTimeblock(t3),
826	      unlock_date: t3.unlock_date,
827	    };
828	  }
829	
830	  // Delete any excluded tracks that were lingering in Tier 3 or Tier 4
831	  const combinedPurgeIds = Array.from(new Set([...t3PurgeIds, ...excludedIds]));
832	  if (combinedPurgeIds.length > 0) {
833	    await Promise.all([
834	      executeOrder({
835	        project_id: projectId,
836	        tier: '3',
837	        order: { action: 'batch_delete', data: combinedPurgeIds },
838	      }),
839	      executeOrder({
840	        project_id: projectId,
841	        tier: '4',
842	        order: { action: 'batch_delete', data: combinedPurgeIds },
843	      }),
844	    ]);
845	  }
846	
847	  if (Object.keys(t4ValidBatchMap).length > 0) {
848	    await executeOrder({
849	      project_id: projectId,
850	      tier: '4',
851	      order: {
852	        action: 'batch_upsert',
853	        data: t4ValidBatchMap,
854	      },
855	    });
856	  }
857	
858	  const badKpiIds = Object.keys(badKpiMap);
859	  if (badKpiIds.length > 0) {
860	    await Promise.all([
861	      executeOrder({
862	        project_id: projectId,
863	        tier: '4',
864	        order: { action: 'batch_delete', data: badKpiIds },
865	      }),
866	      executeOrder({
867	        project_id: projectId,
868	        tier: '3',
869	        order: { action: 'batch_delete', data: badKpiIds },
870	      }),
871	      executeOrder({
872	        project_id: projectId,
873	        tier: 'bad_kpi',
874	        order: { action: 'batch_upsert', data: badKpiMap },
875	      }),
876	    ]);
877	
878	    try {
879	      await syncRawinfoMinusBlacklistToTier1(projectId);
880	    } catch (e) {
881	      console.error('[BadKPI->Static] Lỗi lọc ID khỏi _1_static.db:', e);
882	    }
883	  }
884	
885	  invalidateVinylCache(projectId);
886	  return {
887	    syncedCount: Object.keys(t4ValidBatchMap).length,
888	    purgedCount: badKpiIds.length + t3PurgeIds.length,
889	    badKpiIds,
890	  };
891	}
