897	export async function fetchSampledTracks(
898	  projectId: string,
899	  limit = 50,
900	  channelName?: string,
901	  hazardCap?: number | string | null,
902	  excludeChannel?: string | string[] | null
903	): Promise<{
904	  tracks: PlaylistItem[];
905	  totalCatalogCount: number;
906	  statsMap: Record<string, import('../types').TrackDisplayMeta>;
907	}> {
908	  const samplePayload: any = { limit };
909	  if (channelName && channelName !== 'ALL') {
910	    samplePayload.channel_name = channelName;
911	  }
912	  if (excludeChannel && excludeChannel !== 'NONE' && excludeChannel !== 'ALL') {
913	    samplePayload.exclude_channel = excludeChannel;
914	  }
915	  if (hazardCap !== undefined && hazardCap !== null && hazardCap !== 'ALL' && hazardCap !== 'NONE') {
916	    samplePayload.hazard_cap = hazardCap;
917	  }
918	
919	  const countPayload: any = {};
920	  if (channelName && channelName !== 'ALL') {
921	    countPayload.channel_name = channelName;
922	  }
923	  if (excludeChannel && excludeChannel !== 'NONE' && excludeChannel !== 'ALL') {
924	    countPayload.exclude_channel = excludeChannel;
925	  }
926	  if (hazardCap !== undefined && hazardCap !== null && hazardCap !== 'ALL' && hazardCap !== 'NONE') {
927	    countPayload.hazard_cap = hazardCap;
928	  }
929	
930	  const [sampleRes, countRes, t4Res, channelStateMap] = await Promise.all([
931	    executeOrder<Record<string, Record<string, unknown>>>({
932	      project_id: projectId,
933	      tier: '1',
934	      order: { action: 'sample', data: samplePayload },
935	    }),
936	    executeOrder<{ count: number }>({
937	      project_id: projectId,
938	      tier: '1',
939	      order: { action: 'count', data: countPayload },
940	    }),
941	    executeOrder<Record<string, Record<string, unknown>>>({
942	      project_id: projectId,
943	      tier: '4',
944	      order: { action: 'read_all' },
945	    }),
946	    fetchChannelState(projectId),
947	  ]);
948	
949	  const statsMap: Record<string, import('../types').TrackDisplayMeta> = {};
950	  if (t4Res.data) {
951	    Object.entries(t4Res.data).forEach(([id, val]) => {
952	      let played = 0;
953	      let hazard_level = 3.0;
954	      let timeblock: string | null = null;
955	      let unlock_date: string | null = null;
956	
957	      if (val && typeof val === 'object' && !Array.isArray(val)) {
958	        const v = val as Record<string, unknown>;
959	        played = Number.isInteger(v.played)
960	          ? (v.played as number)
961	          : parseInt(String(v.played || 0), 10);
962	        const rawHazard = Number(v.hazard_level);
963	        hazard_level = !isNaN(rawHazard) ? rawHazard : 3.0;
964	        timeblock = (v.timeblock as string) || null;
965	        unlock_date = (v.unlock_date as string) || null;
966	      } else if (val !== null && val !== undefined) {
967	        played = parseInt(String(val), 10);
968	      }
969	
970	      statsMap[String(id)] = {
971	        played: Number.isFinite(played) && played >= 0 ? Math.floor(played) : 0,
972	        hazard_level: Math.round(hazard_level * 100) / 100,
973	        timeblock,
974	        unlock_date,
975	      };
976	    });
977	  }
978	
979	  const rawSample = sampleRes.data || {};
980	  const tracks: PlaylistItem[] = Object.entries(rawSample)
981	    .map(([id, val]) => {
982	      const v = (val as Record<string, unknown>) || {};
983	      const trackId = String(id).trim();
984	      const t4 = statsMap[trackId];
985	      const chId = (v.channel_id as string) || (v.channelId as string) || '';
986	      const chState = chId ? channelStateMap[chId] : undefined;
987	
988	      const chHazard = chState ? calculateHazardLevel(chState) : 3.0;
989	      const chPlayed = chState ? calculateTotalPlayed(chState) : 0;
990	      const chTimeblock = chState ? getDominantTimeblock(chState) : null;
991	
992	      const effectiveHazard = t4 ? t4.hazard_level : chHazard;
993	      const effectivePlayed = t4 ? t4.played : chPlayed;
994	      const effectiveTimeblock = t4?.timeblock ?? chTimeblock;
995	
996	      // Update statsMap so track stats are populated
997	      if (!t4 && chState) {
998	        statsMap[trackId] = {
999	          hazard_level: effectiveHazard,
1000	          played: effectivePlayed,
1001	          timeblock: effectiveTimeblock,
1002	          unlock_date: chState.unlock_date,
1003	        };
1004	      }
1005	
1006	      return {
1007	        id: trackId,
1008	        title: (v.title as string) || (v.name as string) || `Track ${id}`,
1009	        channel:
1010	          (v.channel_name as string) ||
1011	          (v.channel as string) ||
1012	          (v.artist as string) ||
1013	          'Unknown Origin',
1014	        channel_id: chId,
1015	        duration: (v.duration as number) ?? null,
1016	        hazard_level: effectiveHazard,
1017	        played: effectivePlayed,
1018	        timeblock: effectiveTimeblock,
1019	      };
1020	    })
1021	    .filter((t) => t.id && t.id.length >= 8);
1022	
1023	  const totalCatalogCount = countRes.data?.count !== undefined ? countRes.data.count : tracks.length;
1024	
1025	  return { tracks, totalCatalogCount, statsMap };
1026	}
