1237	export async function streamPlaylistIngestion(
1238	  options: {
1239	    urls?: string[];
1240	    max_playlists?: number;
1241	    max_per_playlist?: number;
1242	  },
1243	  onEvent: (event: CurlerStreamEvent) => void,
1244	  signal?: AbortSignal
1245	): Promise<void> {
1246	  const res = await fetch(`${API_BASE}/api/v1/curler/stream`, {
1247	    method: 'POST',
1248	    headers: { 'Content-Type': 'application/json' },
1249	    body: JSON.stringify(options),
1250	    signal,
1251	  });
1252	
1253	  if (!res.ok) {
1254	    throw new Error(`Curler stream request failed with HTTP ${res.status}`);
1255	  }
1256	
1257	  if (!res.body) {
1258	    throw new Error('ReadableStream not supported on response body.');
1259	  }
1260	
1261	  const reader = res.body.getReader();
1262	  const decoder = new TextDecoder('utf-8');
1263	  let buffer = '';
1264	
1265	  while (true) {
1266	    const { done, value } = await reader.read();
1267	    if (done) break;
1268	
1269	    buffer += decoder.decode(value, { stream: true });
1270	    const chunks = buffer.split('\n\n');
1271	    buffer = chunks.pop() || '';
1272	
1273	    for (const chunk of chunks) {
1274	      const trimmed = chunk.trim();
1275	      if (trimmed.startsWith('data:')) {
1276	        try {
1277	          const jsonStr = trimmed.slice(5).trim();
1278	          if (jsonStr) {
1279	            const eventData = JSON.parse(jsonStr) as CurlerStreamEvent;
1280	            onEvent(eventData);
1281	          }
1282	        } catch (err) {
1283	          console.warn('[Curler Stream] Failed to parse SSE chunk:', err);
1284	        }
1285	      }
1286	    }
1287	  }
1288	
1289	  if (buffer.trim().startsWith('data:')) {
1290	    try {
1291	      const jsonStr = buffer.trim().slice(5).trim();
1292	      if (jsonStr) {
1293	        const eventData = JSON.parse(jsonStr) as CurlerStreamEvent;
1294	        onEvent(eventData);
1295	      }
1296	    } catch (_) {}
1297	  }
1298	
1299	  // Clear static caches after streaming completes
1300	  for (const k in tier1MemoryCache) delete tier1MemoryCache[k];
1301	  invalidateVinylCache();
1302	}
