import sqlite3, json, math
from collections import Counter

def calc_new_hazard(s3_list, s4_list, s5_list, s6_list, s7_list):
    s3, s4, s5, s6, s7 = len(s3_list), len(s4_list), len(s5_list), len(s6_list), len(s7_list)
    total = s3 + s4 + s5 + s6 + s7
    if total == 0:
        return 3.0

    if s7 > 0:
        h0 = 7.0
        anchor_cost = 70
    elif s6 > 0:
        h0 = 6.0
        anchor_cost = 35
    elif s5 > 0:
        h0 = 5.0
        anchor_cost = 10
    elif s4 > 0:
        h0 = 4.0
        anchor_cost = 2
    else:
        h0 = 3.0
        anchor_cost = 0

    earned_xp = 70 * s7 + 35 * s6 + 10 * s5 + 2 * s4
    surplus_xp = max(0, earned_xp - anchor_cost)
    delta_gain = 0.32 * math.log(1 + surplus_xp / 100.0)
    delta_penalty = 0.25 * math.log(1 + (s3 * 1.5)) if s3 > 0 else 0.0

    raw_score = h0 + delta_gain - delta_penalty
    return round(max(1.0, min(9.99, raw_score)), 2)

