    if score >= 4.5: return 'B+'
    if score >= 4.0: return 'B'
    if score >= 3.5: return 'C+'
    if score >= 3.0: return 'C'
    if score >= 2.5: return 'D+'
    if score >= 2.0: return 'D'
    return 'F'

