c3 = sqlite3.connect("backend/data/projects/music_app/app_data/_3_state.db")
c_bl = sqlite3.connect("backend/data/projects/music_app/app_data/system/black_list.db")

excluded = set([r[0] for r in c_bl.execute("SELECT id FROM tier_blacklist_data").fetchall()])

# Channels
ch_rows = c3.execute("SELECT channel_id, channel_name, score_3_count, score_4_count, score_5_count, score_6_count, score_7_count FROM channel_state").fetchall()
channels = {}
for ch in ch_rows:
    if ch[0] not in excluded:
        channels[ch[0]] = {
            'channel_id': ch[0], 'channel_name': ch[1],
            's3': json.loads(ch[2]), 's4': json.loads(ch[3]), 's5': json.loads(ch[4]), 's6': json.loads(ch[5]), 's7': json.loads(ch[6])
        }

# Tracks in tier 3
t3_rows = c3.execute("SELECT id, score_3_count, score_4_count, score_5_count, score_6_count, score_7_count FROM tier_3_data").fetchall()
t3_map = {}
for t in t3_rows:
    if t[0] not in excluded:
        t3_map[t[0]] = {
            'id': t[0],
            's3': json.loads(t[1]), 's4': json.loads(t[2]), 's5': json.loads(t[3]), 's6': json.loads(t[4]), 's7': json.loads(t[5])
        }

ch_ids = list(channels.keys())
placeholders = ','.join(['?'] * len(ch_ids))
cursor = c1.execute(f"SELECT id, channel_id FROM layer1_static WHERE channel_id IN ({placeholders})", ch_ids)
channel_tracks = {}
for song_id, ch_id in cursor.fetchall():
    channel_tracks.setdefault(ch_id, []).append(song_id)

processed = set()
t4_sim = {}
bad_kpi = {}

for ch_id, ch in channels.items():
    songs = channel_tracks.get(ch_id, [])
    for s_id in songs:
        if s_id in excluded: continue
        processed.add(s_id)
        indiv = t3_map.get(s_id)
        if indiv:
            s3 = ch['s3'] + indiv['s3']
            s4 = ch['s4'] + indiv['s4']
            s5 = ch['s5'] + indiv['s5']
            s6 = ch['s6'] + indiv['s6']
            s7 = ch['s7'] + indiv['s7']
        else:
            s3, s4, s5, s6, s7 = ch['s3'], ch['s4'], ch['s5'], ch['s6'], ch['s7']
        h = calc_new_hazard(s3, s4, s5, s6, s7)
        if h < 2.0:
            bad_kpi[s_id] = h
        else:
            t4_sim[s_id] = h

for s_id, indiv in t3_map.items():
    if s_id in processed or s_id in excluded: continue
    h = calc_new_hazard(indiv['s3'], indiv['s4'], indiv['s5'], indiv['s6'], indiv['s7'])
    if h < 2.0:
        bad_kpi[s_id] = h
    else:
        t4_sim[s_id] = h

print("Total projected to Tier 4:", len(t4_sim))
print("Total bad KPI purged (< 2.0):", len(bad_kpi))

ranks = Counter([get_rank(h) for h in t4_sim.values()])
print("\nRank distribution of entire Tier 4 projected database:")
for r in ['✦', 'Ø', 'Ψ', 'S4', 'S3', 'S2', 'S1', 'A+', 'A', 'B+', 'B', 'C+', 'C', 'D+', 'D', 'F']:
    if ranks[r] > 0:
        print(f"  Rank {r:3s}: {ranks[r]:6d} tracks")

eligible = sum(1 for h in t4_sim.values() if h > 3.0)
print(f"\nEligible for Gallery (hazard > 3.0): {eligible} / {len(t4_sim)} tracks")
